$ErrorActionPreference='Stop';$root=$PSScriptRoot;$base='http://127.0.0.1:8090'
& (Join-Path $root 'Stop-GameBridge.ps1')
& (Join-Path $root 'Start-Prototype.ps1') -NoGodot
Invoke-RestMethod "$base/session/reset" -Method Post|Out-Null
$inputs=@('look around the room','look at the dark discoloration','misty step to the desk','cast Eldritch Blast against the wall','look at the desk','read the receipts','inspect correspondence','investigate the dark mark','investigate the dark mark','carefully investigate the dark mark','examine the painting','move through the study door','enter the study')
$path=Join-Path $root 'eval/live_playability_replay.jsonl';if(Test-Path $path){Remove-Item $path};$rows=@()
foreach($inputText in $inputs){$watch=[Diagnostics.Stopwatch]::StartNew();$response=Invoke-RestMethod "$base/action" -Method Post -ContentType 'application/json' -Body (@{text=$inputText}|ConvertTo-Json);$watch.Stop();$row=[ordered]@{turn=($rows.Count+1);input=$inputText;status=$response.status;narration=$response.narration;roll_feedback=$response.roll_feedback;notebook_changed=$response.notebook_changed;latency_seconds=[math]::Round($watch.Elapsed.TotalSeconds,4)};$rows+=[pscustomobject]$row;$row|ConvertTo-Json -Depth 10 -Compress|Add-Content -Encoding utf8 $path;Write-Host "$($row.turn): $inputText -> $($response.status) $($response.roll_feedback)"}
$telemetry=@(Get-Content (Join-Path $root 'eval/playtest_turns.jsonl')|Select-Object -Last $inputs.Count|ConvertFrom-Json);$summary=[ordered]@{generated_utc=[datetime]::UtcNow.ToString('o');turns=$rows.Count;meaningful=@($telemetry|Where-Object{$_.result_category-eq'MEANINGFUL'}).Count;mundane=@($telemetry|Where-Object{$_.result_category-eq'MUNDANE'}).Count;mechanical_successes=@($telemetry|Where-Object{$_.active_check.Outcome-in@('Success','Exceptional Success')}).Count;mechanical_failures=@($telemetry|Where-Object{$_.active_check.Outcome-in@('Failure','Severe Failure')}).Count;setbacks=@($telemetry|Where-Object{$_.active_check.Outcome-eq'Setback'}).Count;parser_clarifications=@($rows|Where-Object{$_.status-eq'needs_clarification'}).Count;engine_rejections=@($rows|Where-Object{$_.status-eq'engine_rejected'}).Count;roll_indicators=@($rows|Where-Object{$_.roll_feedback}).Count;narrator_retries=@($telemetry|Where-Object{$_.retry_occurred}).Count;fallbacks=@($telemetry|Where-Object{$_.fallback_used}).Count;average_live_latency_seconds=[math]::Round((($rows.latency_seconds|Measure-Object -Average).Average),4)};$summary|ConvertTo-Json -Depth 8|Set-Content -Encoding utf8 (Join-Path $root 'eval/live_playability_replay_summary.json');$summary|ConvertTo-Json -Depth 8
